    {
      "op": "add-edge",
      "source": "start",
      "sourcePort": "output",
      "target": "extractMeta",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "extractMeta",
      "sourcePort": "success",
      "target": "endNode",
      "targetPort": "input"
    },
    {
      "op": "insert-between",
      "upstream": "extractMeta",
      "downstream": "endNode",
      "upstreamPort": "success",
      "id": "legalReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "definitionFile": "/tmp/hitl_def.json",
      "label": "Legal Review",
      "nodeTargetPort": "input",
      "nodeSourcePort": "completed",
      "inputs": {
        "schema": {
          "schemaId": schema_uuid,
          "fields": [
            {"id": "contract_id", "label": "Contract ID", "type": "text", "direction": "input", "binding": "vars.start.output.contract_id"},
            {"id": "contract_value", "label": "Contract Value", "type": "number", "direction": "input", "binding": "vars.start.output.contract_value"},
            {"id": "approved", "label": "Approved", "type": "boolean", "direction": "output", "variable": "vars.approved", "required": True},
            {"id": "legal_notes", "label": "Legal Notes", "type": "text", "direction": "output", "variable": "vars.legalNotes"}
          ],
          "outcomes": [
            {"id": "approve", "name": "Approve", "type": "string", "isPrimary": True, "action": "Continue"},
            {"id": "reject", "name": "Reject", "type": "string", "isPrimary": False, "action": "End"}
          ]
        },
